# Near-extremal expansion of damped ordinary roots, omega = sum_k c_k x^k for k = 0..8 in
# x = 1 - a^2, for the damped modes of ExtremalRootTable.jl (s = -2..2, l <= 4, n <= 3). The c_k
# are computed directly from the Teukolsky equation at a = 1 (order-by-order solvability of the
# bordered radial-angular system in Richartz's representation), in Float64 with a deeper
# truncation as a convergence check, or in 192/256-bit arithmetic for the modes that check did
# not pass (deep truncations, small Re(2 c_0 - m)); no root is fitted. Value: (Leaver inversion index of the
# spin table at a = 0.9995, c_0..c_8, x_max), where x_max = (2 pi Re(2 c_0 - m) / 36.8)^2 is
# the x below which the exponentially small term exp(-2 pi Re(2 omega - a m) / sqrt(x)), which
# the series does not contain, stays below 1e-16. Coefficients are stored bit for bit.
